SELECT [SalesDocument],[SalesDocumentItem(POSNR)] AS [SalesDocumentItemNumber],[SalesOrganization],[DeliveryType],[Delivery],[DeliveryItem],[DeliveryCreatedOn],[DeliveryCreatedAt],[PlannedGoodsMovementDate(WADAT)] AS [DeliveryHeaderPlannedGoodsMovementDate],[DeliveryChangedOn],[MeansOfTransportID],[ActualGoodsMovementDate],[MeansofTransport(TRMTYP)] AS [MeansofTransport],[ProofOfDeliveryDate],[ConfirmationTime],[SequentialLegalDeliveryNumber],[DeliveryItemCategory],[StorageLocation],[LogisticalGroup],[DeliveryQuantitySalesUnit],[DocumentCategoryOfSubsequentDocument],[ActualQuantityDeliveredInStockkeepingUnits],[ActualQuantityDelivered(inSalesUnits)] AS [ActualQuantityDeliveredInSalesUnits],[WorldwideUniqueKeyForLIPSVBELN&LIPSPOSNR] AS [WorldwideUniqueKeyForDeliveryNumberAndDeliveryItem],[LastTimeStamp],[TotalGoodsMovementStatus],[BillingStatus],[DeliveryOverallProcessingStatusOfDocument],[ DeliveryPODStatusOnHeaderLevel] AS [DeliveryProofOfDeliveryStatusOnHeaderLevel],[LoadNumber],[LoadItem],[LoadStatus],[RouteDropNumber],[DeliveryQtyChgReason] AS [DeliveryQuantityChangeReason],[DeliveryQtyChgReasonDesc] AS [DeliveryQuantityChangeReasonDescription]
FROM  [RPT_CONNECTEDSC].[V_OTR_DeliveryData] WITH (NOLOCK)
WHERE DeliveryCreatedOn >= @{split(item(),':')[0]}
AND  DeliveryCreatedOn <= @{split(item(),':')[1]}
AND SalesOrganization in ('US01','US02','US03','US04','US05','US06','US07','US08', 'US8R','US8O') 
       AND DeliveryType IN ( 'LF' )

DECLARE @output VARCHAR(MAX)
set @output ='@{activity('Get_ListOfFiles_Since_LUD').output.childitems}';;

WITH CTE AS (
    SELECT filename AS fileName
    FROM OPENJSON(@output)
    WITH (filename VARCHAR(100) '$.name')
)
SELECT FileName, CONVERT(DATE,LEFT(RIGHT(FileName, 12),8)) AS DatePart
FROM CTE

ORDER BY CONVERT(DATE,LEFT(RIGHT(FileName, 12),8));

